#!/usr/bin/env node

const fs = require("node:fs");
const path = require("node:path");

const rootDir = path.resolve(__dirname, "..");
const libPath = path.join(rootDir, "src-tauri", "src", "lib.rs");
const permissionDir = path.join(
  rootDir,
  "src-tauri",
  "permissions",
  "autogenerated"
);
const capabilityPath = path.join(rootDir, "src-tauri", "capabilities", "default.json");

const readText = (filePath) => fs.readFileSync(filePath, "utf8");

const toCapabilityPermission = (commandName) =>
  `allow-${commandName.replaceAll("_", "-")}`;

const extractRegisteredCommands = () => {
  const libSource = readText(libPath);
  const handlerMatch = libSource.match(/generate_handler!\s*\[([\s\S]*?)\]\)/);

  if (!handlerMatch) {
    throw new Error("Could not find tauri::generate_handler![...] in src-tauri/src/lib.rs.");
  }

  const commandPaths = Array.from(
    handlerMatch[1].matchAll(/commands(?:::[A-Za-z0-9_]+)+/g),
    (match) => match[0]
  );

  return Array.from(
    new Set(commandPaths.map((commandPath) => commandPath.split("::").at(-1)))
  ).sort();
};

const getAutogeneratedPermissionNames = () =>
  fs
    .readdirSync(permissionDir)
    .filter((fileName) => fileName.endsWith(".toml"))
    .map((fileName) => path.basename(fileName, ".toml"))
    .sort();

const getCapabilityPermissions = () => {
  const capability = JSON.parse(readText(capabilityPath));
  if (!Array.isArray(capability.permissions)) {
    throw new Error("src-tauri/capabilities/default.json must contain a permissions array.");
  }

  return new Set(capability.permissions);
};

const commands = extractRegisteredCommands();
const commandSet = new Set(commands);
const permissionNames = getAutogeneratedPermissionNames();
const permissionNameSet = new Set(permissionNames);
const capabilityPermissions = getCapabilityPermissions();
const expectedCapabilityPermissions = new Set(commands.map(toCapabilityPermission));

const missingPermissionFiles = commands.filter(
  (commandName) => !permissionNameSet.has(commandName)
);
const stalePermissionFiles = permissionNames.filter(
  (permissionName) => !commandSet.has(permissionName)
);
const missingCapabilityPermissions = commands
  .map((commandName) => ({
    commandName,
    permission: toCapabilityPermission(commandName),
  }))
  .filter(({ permission }) => !capabilityPermissions.has(permission));
const staleCapabilityPermissions = Array.from(capabilityPermissions)
  .filter((permission) => permission.startsWith("allow-"))
  .filter((permission) => !expectedCapabilityPermissions.has(permission))
  .sort();

const failures = [];

if (missingPermissionFiles.length > 0) {
  failures.push(
    `Missing autogenerated permission files: ${missingPermissionFiles
      .map((commandName) => `${commandName}.toml`)
      .join(", ")}`
  );
}

if (stalePermissionFiles.length > 0) {
  failures.push(
    `Stale autogenerated permission files: ${stalePermissionFiles
      .map((permissionName) => `${permissionName}.toml`)
      .join(", ")}`
  );
}

if (missingCapabilityPermissions.length > 0) {
  failures.push(
    `Missing default capability permissions: ${missingCapabilityPermissions
      .map(({ permission }) => permission)
      .join(", ")}`
  );
}

if (staleCapabilityPermissions.length > 0) {
  failures.push(
    `Stale default capability permissions: ${staleCapabilityPermissions.join(", ")}`
  );
}

if (failures.length > 0) {
  console.error("Tauri command alignment failed:");
  for (const failure of failures) {
    console.error(`- ${failure}`);
  }
  process.exit(1);
}

console.log(
  `Verified ${commands.length} Tauri command registrations, permission files, and capability entries.`
);
